import { useCallback, useState } from 'react';
import { JxTagInput, JxChip } from '@jinx-ui/react';

interface ArticleTagsInputProps {
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagsInput({ defaultValue = [], onChange }: ArticleTagsInputProps) {
  const [tags, setTags] = useState<string[]>(defaultValue);

  const updateTags = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange]
  );

  const removeTag = useCallback(
    (tag: string) => {
      updateTags(tags.filter((t) => t !== tag));
    },
    [tags, updateTags]
  );

  return (
    <div>
      <JxTagInput
        ariaLabel="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={updateTags}
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 8 }}>
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

